const GRAMMAR_QUESTIONS=[
{t:"一般现在时",q:"She ___ to school every day.",o:["go","goes","going","went"],a:1,e:"第三人称单数she后动词加es。"},
{t:"现在进行时",q:"Look! The dog ___ in the park.",o:["run","runs","is running","ran"],a:2,e:"Look提示正在发生，用现在进行时is+doing。"},
{t:"一般现在时",q:"I ___ basketball on Monday.",o:["play","plays","playing","played"],a:0,e:"I后动词用原形。"},
{t:"现在进行时",q:"They ___ TV now.",o:["watch","watches","are watching","watched"],a:2,e:"now提示正在发生，用are+doing。"},
{t:"一般现在时",q:"He ___ swimming on Tuesday.",o:["go","goes","going","went"],a:1,e:"第三人称单数he后动词加es。"},
{t:"频度副词",q:"How ___ do you play football?",o:["many","often","much","old"],a:1,e:"问频率用how often。"},
{t:"must/mustn't",q:"You ___ shout in the library.",o:["must","mustn't","can","do"],a:1,e:"图书馆不能大声叫，用mustn't。"},
{t:"比较级",q:"An elephant is ___ than a cat.",o:["big","bigger","biggest","biger"],a:1,e:"比较级加er，big变bigger。"},
{t:"比较级",q:"My sister is ___ than me.",o:["tall","taller","tallest","taller than"],a:1,e:"比较级加er。"},
{t:"最高级",q:"The blue whale is the ___ animal.",o:["big","bigger","biggest","biger"],a:2,e:"最高级加est，big变biggest。"},
{t:"there be句型",q:"___ a book on the desk.",o:["There is","There are","There be","Is there"],a:0,e:"单数用There is。"},
{t:"there be句型",q:"___ many clouds in the sky.",o:["There is","There are","There be","Are there"],a:1,e:"复数用There are。"},
{t:"can/can't",q:"A fish ___ fly.",o:["can","can't","is","do"],a:1,e:"鱼不会飞，用can't。"},
{t:"介词",q:"The book is ___ the table.",o:["in","on","at","to"],a:1,e:"在桌子上用on。"},
{t:"介词",q:"We play football ___ Monday.",o:["in","on","at","to"],a:1,e:"星期几前面用on。"},
{t:"现在进行时",q:"What ___ you doing?",o:["are","is","do","does"],a:0,e:"you配are。"},
{t:"like doing",q:"I like ___ books.",o:["read","reads","reading","readed"],a:2,e:"like后加doing。"},
{t:"have/has",q:"She ___ a new bike.",o:["have","has","having","had"],a:1,e:"第三人称单数用has。"},
{t:"一般疑问句",q:"___ you like apples?",o:["Do","Does","Are","Is"],a:0,e:"you配Do。"},
{t:"特殊疑问词",q:"___ is the weather today? It's sunny.",o:["What","How","Where","When"],a:1,e:"问天气用How。"},
{t:"不可数名词",q:"I want to drink some ___.",o:["waters","water","a water","the waters"],a:1,e:"water是不可数名词，没有复数。"},
{t:"方位介词",q:"The cat is ___ the box.",o:["on","in","under","behind"],a:1,e:"里面用in。"},
{t:"物主代词",q:"This is ___ book. (我的)",o:["I","me","my","mine"],a:2,e:"我的书用my book。"},
{t:"be动词",q:"They ___ students.",o:["is","are","am","be"],a:1,e:"they配are。"}
];

const ENGLISH_READINGS=[
{t:"My Day",p:"My name is Tom. I get up at seven o'clock. I have breakfast at half past seven. I go to school at eight o'clock. I have lunch at school. I go home at four o'clock.",q:["What time does Tom get up?","Where does Tom have lunch?","What time does Tom go home?"],a:["Seven o'clock","At school","Four o'clock"]},
{t:"My Pet",p:"I have a pet rabbit. Its name is Snow. It is white and soft. It likes eating carrots. I play with Snow every day. I love my rabbit.",q:["What is the pet's name?","What color is the rabbit?","What does it like eating?"],a:["Snow","White","Carrots"]},
{t:"The Weather",p:"Today is sunny and warm. The sky is blue. There are some white clouds. I can see a rainbow after the rain. I like sunny days.",q:["How is the weather today?","What color is the sky?","What can you see after the rain?"],a:["Sunny and warm","Blue","A rainbow"]},
{t:"At the Zoo",p:"I went to the zoo on Sunday. I saw lions, pandas and monkeys. The lions were sleeping. The pandas were eating bamboo. The monkeys were climbing trees.",q:["When did I go to the zoo?","What were the lions doing?","What were the pandas doing?"],a:["Sunday","Sleeping","Eating bamboo"]},
{t:"My Family",p:"There are four people in my family. My father is a doctor. My mother is a teacher. I have a little sister. She is three years old. We are a happy family.",q:["How many people in the family?","What does the father do?","How old is the sister?"],a:["Four","A doctor","Three years old"]},
{t:"My Favorite Food",p:"My favorite food is pasta. My mum makes pasta for dinner. I also like salad and soup. I don't like cheese. I drink milk every day.",q:["What is the favorite food?","What doesn't the child like?","What does the child drink every day?"],a:["Pasta","Cheese","Milk"]}
];

const LISTENING_DIALOGUES=[
{t:"问时间",d:"A: What time is it? B: It's seven o'clock.",q:"What time is it?",o:["Six o'clock","Seven o'clock","Eight o'clock"],a:1,e:"B说'It's seven o'clock'，所以时间是七点(Seven o'clock)。"},
{t:"问天气",d:"A: How's the weather today? B: It's sunny and warm.",q:"How's the weather?",o:["Rainy","Sunny and warm","Cloudy"],a:1,e:"B说'It's sunny and warm'，天气晴朗温暖(Sunny and warm)。"},
{t:"问颜色",d:"A: What color is your bag? B: My bag is blue.",q:"What color is the bag?",o:["Red","Blue","Green"],a:1,e:"B说'My bag is blue'，所以书包是蓝色的(Blue)。"},
{t:"问动物",d:"A: What's your favorite animal? B: I like pandas. They're cute.",q:"What's the favorite animal?",o:["Lions","Pandas","Monkeys"],a:1,e:"B说'I like pandas'，所以最喜欢的动物是熊猫(Pandas)。"},
{t:"问运动",d:"A: What do you do on Monday? B: I play basketball.",q:"What does B do on Monday?",o:["Play football","Play basketball","Go swimming"],a:1,e:"B说'I play basketball'，所以B周一打篮球(Play basketball)。"},
{t:"问食物",d:"A: What's your favorite food? B: I like pasta.",q:"What's the favorite food?",o:["Pizza","Pasta","Soup"],a:1,e:"B说'I like pasta'，所以最喜欢的食物是意面(Pasta)。"},
{t:"问地点",d:"A: Where is the library? B: It's next to the hospital.",q:"Where is the library?",o:["Next to the school","Next to the hospital","Next to the park"],a:1,e:"B说'It's next to the hospital'，图书馆在医院旁边(Next to the hospital)。"},
{t:"问年龄",d:"A: How old are you? B: I'm eight years old.",q:"How old is B?",o:["Seven","Eight","Nine"],a:1,e:"B说'I'm eight years old'，所以B八岁(Eight)。"},
{t:"问天气2",d:"A: Is it raining? B: No, it's not. It's windy.",q:"How's the weather?",o:["Raining","Windy","Sunny"],a:1,e:"B说'No, it's not. It's windy'，所以天气是有风(Windy)。"},
{t:"问科目",d:"A: What's your favorite subject? B: I like English.",q:"What's the favorite subject?",o:["Math","English","Chinese"],a:1,e:"B说'I like English'，所以最喜欢的科目是英语(English)。"},
{t:"问数量",d:"A: How many books do you have? B: I have ten books.",q:"How many books?",o:["Five","Ten","Fifteen"],a:1,e:"B说'I have ten books'，所以有十本书(Ten)。"},
{t:"问感受",d:"A: Are you tired? B: No, I'm not. I'm excited!",q:"How does B feel?",o:["Tired","Excited","Bored"],a:1,e:"B说'No, I'm not. I'm excited'，所以B感到兴奋(Excited)。"}
];

// ===== Power Up 2 听力测试题（基于U1-U5测试卷） =====
const PU2_LISTENING=[
// ===== U1: A day on the farm =====
{u:1,t:"U1-农场活动",d:"A: What is Lily doing on the farm? B: She is sleeping in the barn.",q:"What is Lily doing?",o:["She sleeps.","She is sleeping.","He is sleeping."],a:1,e:"问现在进行时'Lily正在做什么'，B回答'She is sleeping'（她正在睡觉），用现在进行时be+doing。A选项是一般现在时，C选项主语He不对。"},
{u:1,t:"U1-问起床时间",d:"A: When do you get up? B: I get up at seven.",q:"When does B get up?",o:["We get up on seven.","I get up at seven.","I get up early."],a:1,e:"问'什么时候起床'，B回答'I get up at seven'（我七点起床）。注意介词用at+具体时间点，不用on。A选项介词on错误。"},
{u:1,t:"U1-问是否有",d:"A: Does she like the farm? B: Yes, she does.",q:"Does she like the farm?",o:["Yes, she is.","Yes, Lily is.","Yes, she does."],a:2,e:"问'Does she...?'用does提问，回答也用does。A选项is与does不匹配，B选项缺少动词。"},
{u:1,t:"U1-问是否想要",d:"A: Do you want to go to the forest? B: No, I don't.",q:"Does B want to go to the forest?",o:["No, I'm not.","No, I don't.","Yes, I want."],a:1,e:"用'Do you...?'提问，回答用'No, I don't.'。A选项'm not与do不匹配，C选项缺少to。"},
{u:1,t:"U1-问是什么",d:"A: What is that on the table? B: It's a pencil.",q:"What is on the table?",o:["Yes, it is.","Yes, they are.","It's a pencil."],a:2,e:"问'是什么'，直接回答内容'It's a pencil'。A/B选项是Yes/No回答，不适合What提问。"},
{u:1,t:"U1-农场动物",d:"A: What can you see on the farm? B: I can see cows and sheep. The cows are eating grass.",q:"What are the cows doing?",o:["Sleeping","Eating grass","Drinking water"],a:1,e:"B说'The cows are eating grass'（奶牛正在吃草），用现在进行时描述正在发生的动作。"},
{u:1,t:"U1-住在哪里",d:"A: Where does Sue live? B: Sue lives in the countryside with her parents.",q:"Where does Sue live?",o:["In the city","In the countryside","On the beach"],a:1,e:"B说'Sue lives in the countryside'（Sue住在乡下），countryside意为'乡下、农村'。"},
{u:1,t:"U1-刷牙",d:"A: What do Sam and Lucy do every day? B: They clean their teeth every day.",q:"What do Sam and Lucy do every day?",o:["Clean their teeth","Wash their hands","Take photos"],a:0,e:"B说'They clean their teeth every day'（他们每天刷牙），clean teeth=brush teeth，意为'刷牙'。"},
// ===== U2: My week =====
{u:2,t:"U2-听单词",d:"A: What word did you hear? B: The word is 'elbow'.",q:"Which word did B hear?",o:["Elbow","Goggles","Sweat"],a:0,e:"B说听到的单词是'elbow'（肘部）。goggles是护目镜，sweat是汗水。"},
{u:2,t:"U2-听单词2",d:"A: What word did you hear? B: The word is 'Tuesday'.",q:"Which word did B hear?",o:["Tuesday","Sunday","Weekday"],a:0,e:"B说听到的单词是'Tuesday'（星期二）。Sunday是星期日，weekday是工作日。"},
{u:2,t:"U2-必须完成",d:"A: What must he do? B: He must finish his homework before 9 o'clock.",q:"What must he do?",o:["Finish homework before 9 o'clock","Write an email on Monday","Get up early"],a:0,e:"B说'He must finish his homework before 9 o'clock'（他必须在9点前完成作业），must表示必须，before意为'在...之前'。"},
{u:2,t:"U2-多久一次",d:"A: How often do you write an email? B: Once a week.",q:"How often does B write an email?",o:["Once a week","I don't write emails","I like writing emails"],a:0,e:"问'多久一次'，B回答'Once a week'（一周一次）。其他选项没有回答频率。"},
{u:2,t:"U2-是否迟到",d:"A: Does Jack get up late? B: No, he never gets up late.",q:"Does Jack get up late?",o:["He often gets up late","He never gets up late","Yes, he does"],a:1,e:"B说'He never gets up late'（他从不晚起），never表示'从不'，频度副词。"},
{u:2,t:"U2-需要什么",d:"A: Do we need swimming caps? B: No, we don't need to.",q:"Do they need swimming caps?",o:["No, we don't need to.","Yes, we need.","You need your swimming caps."],a:0,e:"B回答'No, we don't need to'（不，我们不需要），don't need to表示'不需要'。"},
{u:2,t:"U2-判断-Lily上学",d:"Lily goes to school five days a week. She gets up at seven o'clock. Her dad seldom drives her to school.",q:"Lily goes to school five days a week.",o:["True","False"],a:0,e:"原文说'Lily goes to school five days a week'（Lily一周上五天学），与陈述一致，所以是True。"},
{u:2,t:"U2-判断-起床时间",d:"Lily goes to school five days a week. She gets up at seven o'clock.",q:"Lily gets up at six o'clock.",o:["True","False"],a:1,e:"原文说'She gets up at seven o'clock'（她七点起床），不是六点，所以是False。"},
{u:2,t:"U2-判断-游泳",d:"Lily wears a swimsuit on Tuesdays. She wears a helmet to protect her head.",q:"Lily wears a helmet to protect her hands.",o:["True","False"],a:1,e:"原文说'She wears a helmet to protect her head'（戴头盔保护头部），不是保护手(hands)，所以是False。"},
{u:2,t:"U2-骨和肌肉",d:"A: What do bones and muscles do? B: Our bones and muscles help us move.",q:"What do bones and muscles do?",o:["Help us move","Help us sleep","Help us eat"],a:0,e:"B说'Our bones and muscles help us move'（骨骼和肌肉帮助我们移动），bones=骨头，muscles=肌肉。"},
{u:2,t:"U2-防晒霜",d:"A: When do you use sun cream? B: Sun cream is always important when you're outside.",q:"When is sun cream important?",o:["When you're sleeping","When you're outside","When you're at home"],a:1,e:"B说'Sun cream is always important when you're outside'（在户外时防晒霜总是重要的），outside=在户外。"},
// ===== U3: Party time =====
{u:3,t:"U3-想当医生",d:"A: Does Tom want to be a teacher? B: No, he doesn't. He wants to be a doctor.",q:"What does Tom want to be?",o:["A film star","A doctor","A teacher"],a:1,e:"B说'He wants to be a doctor'（他想当医生），want to be表示'想成为'。"},
{u:3,t:"U3-想当厨师",d:"A: What does David want to be? B: He wants to be a cook.",q:"What does David want to be?",o:["A cook","A teacher","A doctor"],a:0,e:"B说'He wants to be a cook'（他想当厨师），cook可以作名词表示'厨师'，也可以作动词表示'烹饪'。"},
{u:3,t:"U3-为什么当老师",d:"A: Why do you want to be a teacher? B: Because I'm good at teaching.",q:"Why does B want to be a teacher?",o:["Because I'm good at teaching.","Because I want to help sick people.","Because I am kind."],a:0,e:"B说'Because I'm good at teaching'（因为我擅长教学），be good at=擅长做某事，后接-ing形式。"},
{u:3,t:"U3-喜欢游泳",d:"A: What does Tom like? B: He likes swimming.",q:"What does Tom like?",o:["He's swimming.","He likes swimming.","He often swims."],a:1,e:"B说'He likes swimming'（他喜欢游泳），like doing sth=喜欢做某事。A选项是进行时，不是喜好。"},
{u:3,t:"U3-做家务",d:"Lily is a good student. She likes to help her mother do housework. She always does homework after school.",q:"Is Lily a good student?",o:["Yes, she is.","No, she isn't.","We don't know."],a:0,e:"原文说'Lily is a good student'（Lily是好学生），所以回答Yes, she is.。"},
{u:3,t:"U3-放学后做什么",d:"Lily always does her homework after school. She doesn't sleep late.",q:"What does Lily always do after school?",o:["Plays games","Does homework","Watches TV"],a:1,e:"原文说'She always does her homework after school'（她放学后总是做作业），always表示'总是'。"},
{u:3,t:"U3-想当圣诞老人",d:"A: Why does Lily want to be Father Christmas? B: Because she wants to give presents to children.",q:"Why does Lily want to be Father Christmas?",o:["Because she likes presents.","Because she wants to give presents to children.","Because she likes Christmas."],a:1,e:"B说'Because she wants to give presents to children'（因为她想给孩子们送礼物），give presents=送礼物。"},
{u:3,t:"U3-穿着什么",d:"A: What is Grace wearing? B: Grace is wearing a doctor's costume.",q:"What is Grace wearing?",o:["A teacher's costume","A doctor's costume","A pirate costume"],a:1,e:"B说'Grace is wearing a doctor's costume'（Grace穿着医生服装），wear=穿着，costume=服装/装扮。"},
{u:3,t:"U3-擅长画画",d:"A: What is Peter good at? B: He is good at drawing.",q:"What is Peter good at?",o:["Drawing","Singing","Swimming"],a:0,e:"B说'He is good at drawing'（他擅长画画），be good at+doing sth=擅长做某事。"},
// ===== U4: The family at home =====
{u:4,t:"U4-做蛋糕",d:"A: What is Mum doing? B: She is making a birthday cake for him.",q:"What is Mum doing?",o:["She is making a birthday cake for him.","She can make a birthday cake.","She makes a cake."],a:0,e:"B用现在进行时回答'She is making a birthday cake for him'（她正在为他做生日蛋糕），make a cake=做蛋糕。"},
{u:4,t:"U4-生日在何时",d:"A: When is the birthday? B: It's on the 2nd of December.",q:"When is the birthday?",o:["Yes, in December.","On the 2nd of December.","Monday morning."],a:1,e:"B说'It's on the 2nd of December'（在12月2日），on+具体日期，2nd=second的缩写。"},
{u:4,t:"U4-生日派对",d:"A: What did Eddie get? B: A birthday invitation.",q:"What did Eddie get?",o:["A birthday party","A birthday invitation","A Barbie doll."],a:1,e:"B说'A birthday invitation'（一张生日邀请函），invitation=邀请函。"},
{u:4,t:"U4-派对地点",d:"A: Where is the party? B: At No.23 Garden Street.",q:"Where is the party?",o:["On the weekend.","At No.23 Garden Street.","A beautiful garden."],a:1,e:"B说'At No.23 Garden Street'（在花园街23号），No.=Number，Street=街道。"},
{u:4,t:"U4-邀请函",d:"Eddie invites his friends to his birthday party. The party is on October 16 at 3 o'clock in the afternoon. It's at No.15 Nanjing Road.",q:"Where is Eddie's birthday party?",o:["No.15 Nanjing Road","No.23 Garden Street","No.10 Park Road"],a:0,e:"对话说'It's at No.15 Nanjing Road'（在南京路15号），注意区分不同地址信息。"},
{u:4,t:"U4-判断-邀请朋友",d:"Lily invites some of her best friends to her birthday party.",q:"Lily invites some of her best friends to her birthday party.",o:["True","False"],a:0,e:"原文说'Lily invites some of her best friends to her birthday party'（Lily邀请她最好的朋友们参加生日派对），与陈述一致，所以是True。"},
{u:4,t:"U4-判断-打翻奶昔",d:"Lily spills the milkshake on Sally's new blouse at her birthday party.",q:"Lily spills the milkshake on Sally's new blouse.",o:["True","False"],a:0,e:"原文说'Lily spills the milkshake on Sally's new blouse'（Lily把奶昔洒在了Sally的新衬衫上），与陈述一致。spill=洒/溢出。"},
{u:4,t:"U4-判断-不开心",d:"Lily makes mistakes but her friends still love her. She is happy.",q:"Lily is unhappy because she makes a lot of mistakes.",o:["True","False"],a:1,e:"原文说Lily虽然犯了错但朋友们仍然爱她，她是开心的，不是不开心的(unhappy)，所以是False。"},
{u:4,t:"U4-谁的手更大",d:"A: Whose hands are bigger? B: Helen's hands are bigger than Tom's.",q:"Whose hands are bigger?",o:["Tom's hands","Helen's hands","They are the same"],a:1,e:"B说'Helen's hands are bigger than Tom's'（Helen的手比Tom的大），bigger是比较级，than表示'比'。"},
{u:4,t:"U4-谁的更小",d:"A: My sister's eyes are smaller than mine. B: Really?",q:"Whose eyes are smaller?",o:["My eyes","My sister's eyes","Tom's eyes"],a:1,e:"A说'My sister's eyes are smaller than mine'（我妹妹的眼睛比我的小），mine=我的眼睛，smaller是small的比较级。"},
// ===== U5: Animal world =====
{u:5,t:"U5-美丽的毛发",d:"A: What has the animal got? B: It's got beautiful fur.",q:"What has the animal got?",o:["Beautiful fur","Beautiful feathers","Beautiful scales"],a:0,e:"B说'It's got beautiful fur'（它有美丽的毛发），fur=毛皮，feathers是羽毛（鸟类的）。"},
{u:5,t:"U5-住在悬崖",d:"A: Where do these birds live? B: They live on the cliff. They also live in the trees.",q:"Where do the birds live?",o:["They live in the trees.","They live on the cliff.","Both A and B."],a:2,e:"B说'They live on the cliff. They also live in the trees'（它们住在悬崖上，也住在树上），所以两个都对(Both)。"},
{u:5,t:"U5-最大的动物",d:"A: How big are whales? B: They are the biggest animals in the world.",q:"How big are whales?",o:["The biggest in the sea","Smaller than elephants","The biggest in the world"],a:2,e:"B说'They are the biggest animals in the world'（它们是世界上最大的动物），biggest是big的最高级。"},
{u:5,t:"U5-是什么动物",d:"A: Are those lions? B: No. They are tigers.",q:"What are those animals?",o:["They are lions.","Yes, they are tigers.","No. They are tigers."],a:2,e:"B说'No. They are tigers.'（不，它们是老虎），首先否定不是狮子，然后说是老虎。"},
{u:5,t:"U5-企鹅住哪",d:"A: Where do penguins live? B: They live in the South Pole.",q:"Where do penguins live?",o:["In the South Pole","In Africa","In African grasslands"],a:0,e:"B说'They live in the South Pole'（它们住在南极），South Pole=南极。Africa=非洲，grasslands=草原。"},
{u:5,t:"U5-猫的颜色",d:"A: What color is the cat? B: It's brown.",q:"What color is the cat?",o:["Brown","Green","Red"],a:0,e:"B说'It's brown'（它是棕色的），brown=棕色。注意区分颜色单词。"},
{u:5,t:"U5-喂猫什么",d:"A: What does he do for the cat? B: He feeds the cat some fish.",q:"What does he feed the cat?",o:["Some fish","Some milk","He brushes its fur"],a:0,e:"B说'He feeds the cat some fish'（他给猫喂鱼），feed sb sth=给某人喂某物。"},
{u:5,t:"U5-动物医生",d:"A: What do you call an animal doctor? B: A vet.",q:"What is an animal doctor called?",o:["A dentist","A vet","A doctor"],a:1,e:"B说'A vet'（兽医），vet=veterinarian的缩写，专门给动物看病的医生。dentist=牙医。"},
{u:5,t:"U5-谁孵蛋",d:"A: Who takes care of the baby penguins? B: Father penguins do.",q:"Who takes care of baby penguins?",o:["Father penguins do","Yes, they do","No. Mother penguins do."],a:0,e:"B说'Father penguins do'（企鹅爸爸照顾企鹅宝宝），注意是爸爸(father)不是妈妈(mother)。"},
{u:5,t:"U5-动物在做什么",d:"A: What are the rabbits doing? B: The little brown rabbit is jumping.",q:"What is the rabbit doing?",o:["Jumping","Sleeping","Running"],a:0,e:"B说'The little brown rabbit is jumping'（小棕兔正在跳），用现在进行时描述正在发生的动作。"},
{u:5,t:"U5-最漂亮的女孩",d:"A: Who is the prettiest girl in your class? B: Anna is the prettiest girl in my class.",q:"Who is the prettiest in the class?",o:["Anna","Lily","Sophia"],a:0,e:"B说'Anna is the prettiest girl'（Anna是最漂亮的女孩），prettiest是pretty的最高级，the+最高级。"},
{u:5,t:"U5-老虎吃什么",d:"A: What do tigers eat? B: Tigers are carnivores. They eat meat.",q:"What are tigers?",o:["Carnivores","Herbivores","Omnivores"],a:0,e:"B说'Tigers are carnivores'（老虎是食肉动物），carnivore=食肉动物，herbivore=食草动物，omnivore=杂食动物。"},
{u:5,t:"U5-斑马住哪",d:"A: Where do zebras live? B: Zebras live in African grasslands.",q:"Where do zebras live?",o:["African grasslands","Antarctica","The ocean"],a:0,e:"B说'Zebras live in African grasslands'（斑马住在非洲草原），Africa=非洲，grasslands=草原。"},
{u:5,t:"U5-兔子在哪",d:"A: Where are the baby rabbits? B: Baby rabbits are asleep below the ground.",q:"Where are the baby rabbits?",o:["Above the ground","Below the ground","On the ground"],a:1,e:"B说'Baby rabbits are asleep below the ground'（小兔子在地下睡觉），below=在...下面，above=在...上面。"}
];

// ===== Power Up 3 听力练习题（基于Level 3 Student's Book课程内容） =====
// Unit 1: Let's travel! (马戏团/旅行) - 时间表达/疑问词/was-were/could-couldn't
// Unit 2: Food and drink (饮食) - 关系从句/过去时/食物营养
// Unit 3: Parts of the body (身体部位) - 比较级最高级/健康问题
// Unit 4: Explorers (探险) - 探险词汇/材料/过去时动词
// Unit 5: School subjects (学校科目) - 学校词汇/f-ph发音
// Unit 6: Animal world (动物世界) - 动物/比较级
const PU3_LISTENING=[
// ===== U1: Let's travel! (马戏团与旅行) =====
{u:1,t:"U1-马戏团时间",d:"A: What time do the acrobats get up? B: They get up at half past six.",q:"What time do the acrobats get up?",o:["At six o'clock","At half past six","At seven o'clock"],a:1,e:"B说'They get up at half past six'（他们六点半起床），half past six=六点半。注意half past表示'半点'。"},
{u:1,t:"U1-为什么早起",d:"A: Why do they have breakfast early? B: Because they have to practice before the show.",q:"Why do they have breakfast early?",o:["Because they have to practice","Because they like mornings","Because the show starts early"],a:0,e:"B说'Because they have to practice before the show'（因为他们必须在演出前练习），have to=必须，practice=练习。"},
{u:1,t:"U1-杂技演员做什么",d:"A: What does an acrobat do? B: An acrobat performs acrobatic moves on stage.",q:"What does an acrobat do?",o:["Performs acrobatic moves on stage","Cooks food in the kitchen","Teaches children at school"],a:0,e:"B说'An acrobat performs acrobatic moves on stage'（杂技演员在舞台上表演杂技动作），acrobat=杂技演员，perform=表演，stage=舞台。"},
{u:1,t:"U1-能做什么",d:"A: Could the acrobats do backflips when they were young? B: No, they couldn't. But now they can.",q:"Could the acrobats do backflips when they were young?",o:["Yes, they could","No, they couldn't","They can do it now"],a:1,e:"B说'No, they couldn't'（不，他们不能），could/couldn't是can/can't的过去式，表示过去的能力。"},
{u:1,t:"U1-马戏团在哪里",d:"A: Where is the circus? B: The circus is near the river. It has a big stage.",q:"Where is the circus?",o:["Near the school","Near the river","Near the park"],a:1,e:"B说'The circus is near the river'（马戏团在河边附近），circus=马戏团，near=在...附近，river=河。"},
{u:1,t:"U1-舞台上的表演",d:"A: What can you see on the stage? B: I can see acrobats on the trapeze. They are flying through the air!",q:"What can you see on the stage?",o:["Acrobats on the trapeze","Clowns with balloons","Animals jumping"],a:0,e:"B说'I can see acrobats on the trapeze'（我看到杂技演员在秋千上），trapeze=高空秋千，fly through the air=在空中飞。"},
{u:1,t:"U1-判断-马戏团旅行",d:"A: Where does the circus travel? B: The circus travels all around the world. They visit many countries.",q:"The circus only performs in one country.",o:["True","False"],a:1,e:"B说'The circus travels all around the world'（马戏团环游世界），不是只在一个国家表演，所以是False。all around the world=环游世界。"},
{u:1,t:"U1-判断-练习时间",d:"A: When do acrobats practice? B: Acrobats practice every day before breakfast. They never skip practice.",q:"Acrobats practice every day before breakfast.",o:["True","False"],a:0,e:"B说'Acrobats practice every day before breakfast'（杂技演员每天早餐前练习），与陈述一致，所以是True。skip=跳过/缺席。"},
{u:1,t:"U1-蹦床",d:"A: What is the acrobat doing on the trampoline? B: The acrobat is bouncing high on the trampoline.",q:"What is the acrobat doing?",o:["Bouncing on the trampoline","Sleeping on the stage","Eating in the tent"],a:0,e:"B说'The acrobat is bouncing high on the trampoline'（杂技演员在蹦床上高高弹跳），trampoline=蹦床，bounce=弹跳，用现在进行时描述正在发生的动作。"},
{u:1,t:"U1-问谁表演",d:"A: Who performs in the circus? B: Acrobats, clowns, and animals perform in the circus.",q:"Who performs in the circus?",o:["Only acrobats","Acrobats, clowns, and animals","Only clowns"],a:1,e:"B说'Acrobats, clowns, and animals perform in the circus'（杂技演员、小丑和动物在马戏团表演），clown=小丑。注意问'Who'时回答用完整内容。"},
// ===== U2: Food and drink (饮食与营养) =====
{u:2,t:"U2-什么食物",d:"A: What food do you like? B: I like pancakes. Americans have them for breakfast with sauce.",q:"What food does B like?",o:["Pancakes","Noodles","Rice"],a:0,e:"B说'I like pancakes'（我喜欢煎饼），pancake=煎饼， Americans have it for breakfast with sauce=美国人配酱汁当早餐吃。"},
{u:2,t:"U2-食物原料",d:"A: What is a pancake made of? B: It is made of eggs, milk and flour.",q:"What is a pancake made of?",o:["Eggs, milk and flour","Bread and butter","Rice and water"],a:0,e:"B说'It is made of eggs, milk and flour'（它由鸡蛋、牛奶和面粉制成），be made of=由...制成，flour=面粉。"},
{u:2,t:"U2-最喜欢的饮料",d:"A: What is your favorite drink? B: My favorite drink is orange juice. It has lots of vitamin C.",q:"What is B's favorite drink?",o:["Milk","Orange juice","Water"],a:1,e:"B说'My favorite drink is orange juice'（我最喜欢的饮料是橙汁），vitamin C=维生素C，orange juice=橙汁。"},
{u:2,t:"U2-健康饮食",d:"A: Why is fruit important? B: Fruit is important because it has vitamins. We should eat fruit every day.",q:"Why is fruit important?",o:["Because it has vitamins","Because it is sweet","Because it is cheap"],a:0,e:"B说'Fruit is important because it has vitamins'（水果重要因为它含有维生素），vitamin=维生素，should=应该。"},
{u:2,t:"U2-过去吃的东西",d:"A: What did you eat yesterday? B: I ate fish and chips. When I finished, I had an apple.",q:"What did B eat yesterday?",o:["Fish and chips","Rice and chicken","Bread and cheese"],a:0,e:"B说'I ate fish and chips'（我吃了炸鱼薯条），ate是eat的过去式，fish and chips=炸鱼薯条（英国传统食物）。"},
{u:2,t:"U2-判断-营养",d:"A: Tell me about nutrition. B: We need carbohydrates for energy. We need protein for muscles. We need vitamins to stay healthy.",q:"We need protein for energy.",o:["True","False"],a:1,e:"B说'We need carbohydrates for energy'（我们需要碳水化合物提供能量），蛋白质(protein)是用来长肌肉的，不是提供能量，所以是False。"},
{u:2,t:"U2-判断-早餐",d:"A: What did Lily have for breakfast? B: Lily had cereal with milk and a banana for breakfast.",q:"Lily had cereal with milk and a banana for breakfast.",o:["True","False"],a:0,e:"B说'Lily had cereal with milk and a banana for breakfast'（Lily早餐吃了麦片加牛奶和一根香蕉），与陈述一致，所以是True。cereal=麦片。"},
{u:2,t:"U2-关系从句",d:"A: What is a kitchen? B: A kitchen is the place where my mum cooks dinner.",q:"What is a kitchen?",o:["A place where mum cooks dinner","A place where we sleep","A place where we watch TV"],a:0,e:"B说'A kitchen is the place where my mum cooks dinner'（厨房是妈妈做饭的地方），where引导关系从句，修饰place。"},
{u:2,t:"U2-老人与鱼",d:"A: What did the old man catch? B: The old man caught a big fish. But the fish was too strong.",q:"What did the old man catch?",o:["A big fish","A small fish","Nothing"],a:0,e:"B说'The old man caught a big fish'（老人抓到了一条大鱼），caught是catch的过去式，too strong=太强壮。"},
{u:2,t:"U2-判断-鱼的结局",d:"A: What happened to the fish? B: The fish was too strong. It pulled the boat for a long time. In the end, the old man lost the fish.",q:"The old man kept the fish and went home happily.",o:["True","False"],a:1,e:"B说'In the end, the old man lost the fish'（最后老人失去了鱼），不是开心回家，所以是False。lost=失去（lose的过去式）。"},
// ===== U3: Parts of the body (身体部位与健康) =====
{u:3,t:"U3-身体部位",d:"A: What do we use to see? B: We use our eyes to see. We use our ears to hear.",q:"What do we use to see?",o:["Our eyes","Our ears","Our hands"],a:0,e:"B说'We use our eyes to see'（我们用眼睛看），use...to...=用...做...，eyes=眼睛，ears=耳朵。"},
{u:3,t:"U3-比较-谁更高",d:"A: Who is taller? B: Tom is taller than Jerry. But Jerry is stronger than Tom.",q:"Who is taller?",o:["Tom","Jerry","They are the same height"],a:0,e:"B说'Tom is taller than Jerry'（Tom比Jerry高），taller是tall的比较级，than=比。但Jerry更强壮(stronger)。"},
{u:3,t:"U3-最高级-最快",d:"A: Who is the fastest runner in your class? B: Sam is the fastest runner in my class. He can run very quickly.",q:"Who is the fastest runner?",o:["Sam","Tom","Jerry"],a:0,e:"B说'Sam is the fastest runner'（Sam是最快的跑步者），fastest是fast的最高级，the+最高级。"},
{u:3,t:"U3-健康问题",d:"A: What is the matter with you? B: I have a headache. I need to see a doctor.",q:"What is the matter with B?",o:["A headache","A stomachache","A toothache"],a:0,e:"B说'I have a headache'（我头痛），headache=头痛，What is the matter?=怎么了？need to=需要。"},
{u:3,t:"U3-需要什么",d:"A: What do you need to do to stay healthy? B: I need to exercise every day and eat good food.",q:"What does B need to do to stay healthy?",o:["Exercise every day and eat good food","Sleep all day","Watch TV"],a:0,e:"B说'I need to exercise every day and eat good food'（我需要每天锻炼并吃好的食物），need to+动词原形=需要做某事，exercise=锻炼。"},
{u:3,t:"U3-骨骼作用",d:"A: What do bones do? B: Our bones hold us up. They protect our inside parts like the heart and lungs.",q:"What do bones do?",o:["They hold us up and protect inside parts","They help us see","They help us hear"],a:0,e:"B说'Our bones hold us up. They protect our inside parts'（骨骼支撑我们，保护内部器官），protect=保护，heart=心脏，lungs=肺。"},
{u:3,t:"U3-判断-锻炼身体",d:"A: Why is exercise important? B: Exercise makes our muscles strong. It also helps our heart. We should exercise every day.",q:"Exercise helps our heart.",o:["True","False"],a:0,e:"B说'It also helps our heart'（锻炼也帮助心脏），与陈述一致，所以是True。muscle=肌肉，heart=心脏。"},
{u:3,t:"U3-判断-比较级",d:"A: Compare the animals. B: An elephant is bigger than a cat. A cheetah is faster than a turtle.",q:"A cat is bigger than an elephant.",o:["True","False"],a:1,e:"B说'An elephant is bigger than a cat'（大象比猫大），不是猫比大象大，所以是False。bigger=更大的。"},
{u:3,t:"U3-最强壮的",d:"A: Who is the strongest in your family? B: My dad is the strongest in my family. He can lift heavy things.",q:"Who is the strongest in B's family?",o:["B's dad","B's mum","B's sister"],a:0,e:"B说'My dad is the strongest'（我爸爸是最强壮的），strongest是strong的最高级，lift=举起。"},
{u:3,t:"U3-身体锻炼",d:"A: What should we do to work our body? B: We should run, jump, and play sports. This makes our body strong.",q:"What should we do to work our body?",o:["Run, jump, and play sports","Sleep and rest","Sit and read"],a:0,e:"B说'We should run, jump, and play sports'（我们应该跑、跳和做运动），work our body=锻炼身体，should=应该。"},
// ===== U4: Explorers (探险与发现) =====
{u:4,t:"U4-探险地点",d:"A: Where did the explorers go? B: They went to an island. The island was in the middle of the ocean.",q:"Where did the explorers go?",o:["To an island","To a city","To a mountain"],a:0,e:"B说'They went to an island'（他们去了岛屿），island=岛屿，in the middle of=在...中间，ocean=海洋。went是go的过去式。"},
{u:4,t:"U4-丛林冒险",d:"A: What did they see in the jungle? B: They saw many plants and a beautiful waterfall in the jungle.",q:"What did they see in the jungle?",o:["Many plants and a waterfall","Many animals and caves","Many houses and roads"],a:0,e:"B说'They saw many plants and a beautiful waterfall'（他们看到了很多植物和美丽的瀑布），jungle=丛林，waterfall=瀑布，saw是see的过去式。"},
{u:4,t:"U4-夜晚的天空",d:"A: What could they see at night? B: At night, they could see the moon and many stars in the sky.",q:"What could they see at night?",o:["The moon and stars","The sun and clouds","The ocean and waves"],a:0,e:"B说'they could see the moon and many stars in the sky'（他们能看到月亮和天空中的很多星星），moon=月亮，star=星星，sky=天空，could=能（can的过去式）。"},
{u:4,t:"U4-材料-什么做的",d:"A: What are the wings made of? B: The wings are made of paper and wood.",q:"What are the wings made of?",o:["Paper and wood","Metal and glass","Plastic and rubber"],a:0,e:"B说'The wings are made of paper and wood'（翅膀是用纸和木头做的），be made of=由...制成，wings=翅膀/机翼。"},
{u:4,t:"U4-材料-金子",d:"A: What is the crown made of? B: It is made of gold. Gold is a precious metal.",q:"What is the crown made of?",o:["Gold","Silver","Paper"],a:0,e:"B说'It is made of gold'（它是由金子做的），gold=金子，precious metal=贵金属，crown=皇冠。"},
{u:4,t:"U4-设计建议",d:"A: Shall we design some props? B: Let's design the sea. We could use blue paper.",q:"What does B suggest designing?",o:["The sea","The sky","The mountain"],a:0,e:"B说'Let's design the sea. We could use blue paper'（让我们设计海洋，可以用蓝纸），Shall we...?=我们...好吗？Let's...=让我们...，prop=道具。"},
{u:4,t:"U4-过去时-航海",d:"A: What did the sailors do? B: The sailors sailed on the sea. They caught fish and threw their nets.",q:"What did the sailors do?",o:["Sailed on the sea and caught fish","Flew in the sky","Drove on the road"],a:0,e:"B说'The sailors sailed on the sea. They caught fish and threw their nets'（水手在海上航行，抓鱼撒网），sailed是sail的过去式，caught是catch的过去式，threw是throw的过去式。"},
{u:4,t:"U4-判断-探险发现",d:"A: What did the explorers find? B: They found a cave on the island. Inside the cave, there was a treasure chest.",q:"The explorers found a treasure chest in a cave.",o:["True","False"],a:0,e:"B说'They found a cave on the island. Inside the cave, there was a treasure chest'（他们在岛上发现了一个洞穴，洞穴里有宝箱），与陈述一致，所以是True。treasure chest=宝箱。"},
{u:4,t:"U4-判断-波涛",d:"A: What happened on the sea? B: The waves were very big. The boat bounced on the waves. They were scared.",q:"The waves were small and calm.",o:["True","False"],a:1,e:"B说'The waves were very big'（波浪很大），不是小而平静的，所以是False。wave=海浪，bounce=弹跳，scared=害怕的。"},
{u:4,t:"U4-世界有多大",d:"A: How big is the world? B: The world is very big. There are many countries, oceans, and mountains.",q:"How big is the world?",o:["Very big with many countries","Very small","Only one country"],a:0,e:"B说'The world is very big. There are many countries, oceans, and mountains'（世界很大，有很多国家、海洋和山脉），world=世界，country=国家，ocean=海洋，mountain=山。"},
// ===== U5: School subjects (学校科目) =====
{u:5,t:"U5-最喜欢的科目",d:"A: What is your favorite subject? B: My favorite subject is science. I love doing experiments.",q:"What is B's favorite subject?",o:["Math","Science","English"],a:1,e:"B说'My favorite subject is science'（我最喜欢的科目是科学），science=科学，experiment=实验。"},
{u:5,t:"U5-数学课",d:"A: What do you do in math class? B: We learn about numbers. We also learn to add and subtract.",q:"What do they learn in math class?",o:["Numbers, adding and subtracting","Drawing and painting","Singing and dancing"],a:0,e:"B说'We learn about numbers. We also learn to add and subtract'（我们学数字，也学加减法），add=加，subtract=减。"},
{u:5,t:"U5-f和ph发音",d:"A: Which words have the 'f' sound? B: Fish, phone, and photo all start with the 'f' sound. Fish uses 'f', phone and photo use 'ph'.",q:"Which letter makes the 'f' sound in 'phone'?",o:["f","ph","ff"],a:1,e:"B说'phone and photo use ph'（phone和photo用ph），ph组合也发/f/的音，和字母f一样。phone=电话，photo=照片。"},
{u:5,t:"U5-体育课",d:"A: What do you do in PE class? B: In PE class, we run, jump, and play games. PE is fun!",q:"What do they do in PE class?",o:["Run, jump, and play games","Read books","Write stories"],a:0,e:"B说'In PE class, we run, jump, and play games'（体育课上我们跑、跳和玩游戏），PE=Physical Education体育，fun=有趣。"},
{u:5,t:"U5-美术课",d:"A: What do you do in art class? B: In art class, we draw and paint. I like painting landscapes.",q:"What do they do in art class?",o:["Draw and paint","Sing and dance","Read and write"],a:0,e:"B说'In art class, we draw and paint'（美术课上我们画画），art=美术，draw=画（素描），paint=画（颜料画），landscape=风景画。"},
{u:5,t:"U5-判断-科学课",d:"A: Tell me about science class. B: In science class, we learn about plants and animals. We sometimes do experiments in the lab.",q:"They do experiments in the lab in science class.",o:["True","False"],a:0,e:"B说'We sometimes do experiments in the lab'（我们有时在实验室做实验），与陈述一致，所以是True。lab=laboratory实验室。"},
{u:5,t:"U5-判断-音乐课",d:"A: What about music class? B: In music class, we sing songs and play instruments. I play the piano.",q:"B plays the guitar in music class.",o:["True","False"],a:1,e:"B说'I play the piano'（我弹钢琴），不是弹吉他(guitar)，所以是False。piano=钢琴，guitar=吉他，instrument=乐器。"},
{u:5,t:"U5-科目时间表",d:"A: When do you have English? B: We have English on Monday and Wednesday. We have math every day.",q:"When do they have English?",o:["Monday and Wednesday","Every day","Only on Friday"],a:0,e:"B说'We have English on Monday and Wednesday'（我们周一和周三上英语课），注意on+星期几。math every day=每天上数学。"},
{u:5,t:"U5-地理课",d:"A: What do you learn in geography? B: In geography, we learn about countries, rivers, and mountains. We look at maps.",q:"What do they learn in geography?",o:["Countries, rivers, and mountains","Numbers and shapes","Songs and dances"],a:0,e:"B说'In geography, we learn about countries, rivers, and mountains'（地理课上我们学国家、河流和山脉），geography=地理，look at maps=看地图。"},
{u:5,t:"U5-历史课",d:"A: What do you do in history class? B: In history, we learn about the past. We learn about kings, queens, and old buildings.",q:"What do they learn about in history?",o:["The past, kings, queens, and old buildings","The future, robots, and spaceships","Numbers and counting"],a:0,e:"B说'In history, we learn about the past. We learn about kings, queens, and old buildings'（历史课上学过去的事情，学国王、女王和老建筑），history=历史，past=过去，king=国王，queen=女王。"},
// ===== U6: Animal world (动物世界) =====
{u:6,t:"U6-大象和蛇",d:"A: Which animal is faster? B: Elephants can move faster than snakes. But snakes can move more quietly.",q:"Which can move faster?",o:["Elephants","Snakes","They are the same"],a:0,e:"B说'Elephants can move faster than snakes'（大象比蛇移动得快），faster是fast的比较级，more quietly是quietly的比较级（副词比较级用more+原级）。"},
{u:6,t:"U6-猴子和老虎",d:"A: Which animal can climb better? B: Monkeys can climb better than tigers. Tigers are better at running.",q:"Which can climb better?",o:["Monkeys","Tigers","They climb the same"],a:0,e:"B说'Monkeys can climb better than tigers'（猴子比老虎更擅长爬），climb=爬，better是well的比较级，be good at=擅长。"},
{u:6,t:"U6-熊和猴子",d:"A: How do bears and monkeys compare? B: Bears can run more quickly than monkeys. But monkeys are smarter.",q:"Which runs more quickly?",o:["Bears","Monkeys","They run the same speed"],a:0,e:"B说'Bears can run more quickly than monkeys'（熊比猴子跑得更快），more quickly是quickly的比较级，smart=聪明的。"},
{u:6,t:"U6-最大的动物",d:"A: What is the biggest land animal? B: The elephant is the biggest land animal. Blue whales are the biggest in the sea.",q:"What is the biggest land animal?",o:["The elephant","The blue whale","The bear"],a:0,e:"B说'The elephant is the biggest land animal'（大象是最大的陆地动物），biggest是big的最高级，land animal=陆地动物，blue whale=蓝鲸。"},
{u:6,t:"U6-最快的动物",d:"A: What is the fastest animal on land? B: The cheetah is the fastest animal on land. It can run very fast.",q:"What is the fastest animal on land?",o:["The cheetah","The elephant","The snake"],a:0,e:"B说'The cheetah is the fastest animal on land'（猎豹是陆地上最快的动物），cheetah=猎豹，fastest=最快的，on land=在陆地上。"},
{u:6,t:"U6-长大想做什么",d:"A: What do you want to be when you grow up? B: When I grow up, I want to be a vet. I love animals.",q:"What does B want to be when they grow up?",o:["A vet","A teacher","A doctor"],a:0,e:"B说'When I grow up, I want to be a vet'（我长大想当兽医），grow up=长大，vet=兽医，want to be=想成为。"},
{u:6,t:"U6-动物栖息地",d:"A: Where do penguins live? B: Penguins live in the South Pole. It is very cold there. They can swim very well.",q:"Where do penguins live?",o:["In the South Pole","In Africa","In the jungle"],a:0,e:"B说'Penguins live in the South Pole'（企鹅住在南极），South Pole=南极，cold=冷的，swim=游泳。"},
{u:6,t:"U6-判断-动物比较",d:"A: Compare these animals. B: A lion is stronger than a cat. A snake is longer than a lizard. An eagle can fly higher than a chicken.",q:"A snake is longer than a lizard.",o:["True","False"],a:0,e:"B说'A snake is longer than a lizard'（蛇比蜥蜴长），与陈述一致，所以是True。longer=更长的，lizard=蜥蜴。"},
{u:6,t:"U6-判断-飞行",d:"A: Can all birds fly? B: No, not all birds can fly. Penguins and ostriches cannot fly. But eagles can fly very high.",q:"All birds can fly.",o:["True","False"],a:1,e:"B说'Not all birds can fly. Penguins and ostriches cannot fly'（不是所有鸟都会飞，企鹅和鸵鸟不会飞），所以'所有鸟都会飞'是False。ostrich=鸵鸟。"},
{u:6,t:"U6-野生动物",d:"A: What is the difference between wild and domestic animals? B: Wild animals live in the forest. Domestic animals live with people.",q:"Where do wild animals live?",o:["In the forest","With people","In the zoo"],a:0,e:"B说'Wild animals live in the forest'（野生动物住在森林里），wild=野生的，domestic=家养的，forest=森林。"},
{u:6,t:"U6-最聪明的动物",d:"A: What is the smartest animal? B: Dolphins are very smart. They can learn tricks and communicate with each other.",q:"What animal is very smart according to B?",o:["Dolphins","Snakes","Bears"],a:0,e:"B说'Dolphins are very smart. They can learn tricks and communicate'（海豚很聪明，能学技巧并交流），dolphin=海豚，communicate=交流，trick=技巧。"}
];
